import { useEffect, useState } from "react";
import { Box, Container, Link, Stack, Typography } from "@mui/material";
import api, { mediaUrl } from "../services/api";
import type { FooterData, SingleResponse } from "../types/home";

const FALLBACK: FooterData = {
  links: [
    { label: "Blog", url: "https://www.doctutorials.com/blog" },
    { label: "About us", url: "https://www.doctutorials.com/about-us" },
    { label: "FAQs", url: "https://www.doctutorials.com/faqs" },
    { label: "Terms & Conditions", url: "https://www.doctutorials.com/terms-conditions" },
    { label: "Contact Us", url: "https://www.doctutorials.com/contact-us" },
    { label: "Privacy Policy", url: "https://www.doctutorials.com/privacy-policy" },
  ],
  email: "help@doctutorials.com",
  phones: "7995111755, 7097634567",
  hours: "10 AM TO 7 PM",
  socials: [
    { url: "https://www.instagram.com/doctutorials" },
    { url: "https://www.youtube.com/doctutorials" },
    { url: "https://t.me/DocTutorials" },
    { url: "https://in.linkedin.com/company/doctutorials" },
    { url: "https://www.facebook.com/doctutorials" },
  ],
};

export default function Footer() {
  const [data, setData] = useState<FooterData>(FALLBACK);

  useEffect(() => {
    api
      .get<SingleResponse<FooterData>>("/footer", {
        params: {
          "populate[links]": true,
          "populate[emailIcon]": true,
          "populate[phoneIcon]": true,
          "populate[socials][populate]": "icon",
        },
      })
      .then((payload) => {
        if (payload.data) setData({ ...FALLBACK, ...payload.data });
      })
      .catch(() => setData(FALLBACK));
  }, []);

  return (
    <Box component="footer" sx={{ backgroundColor: "#edf2fb", py: { xs: 4, md: 5 }, mt: 0 }}>
      <Container maxWidth="lg">
        <Stack
          direction={{ xs: "column", md: "row" }}
          spacing={2}
          justifyContent="center"
          alignItems="center"
          sx={{ mb: 3, flexWrap: "wrap" }}
        >
          {(data.links || []).map((item) => (
            <Link
              key={item.id || item.label}
              href={item.url}
              underline="none"
              sx={{ color: "#17224d", fontSize: 15, px: 1.5, fontWeight: 500 }}
            >
              {item.label}
            </Link>
          ))}
        </Stack>
        <Stack
          direction={{ xs: "column", md: "row" }}
          justifyContent="space-between"
          alignItems="center"
          spacing={3}
        >
          <Stack direction="row" alignItems="center" spacing={1}>
            {mediaUrl(data.emailIcon) ? (
              <Box component="img" src={mediaUrl(data.emailIcon)} alt="" sx={{ width: 22 }} />
            ) : null}
            {data.email ? (
              <Link href={`mailto:${data.email}`} underline="none" sx={{ color: "#17224d" }}>
                {data.email}
              </Link>
            ) : null}
          </Stack>
          <Stack direction="row" spacing={1.5}>
            {(data.socials || []).map((item) => (
              <Link key={item.id || item.url} href={item.url} target="_blank" rel="noopener noreferrer">
                {mediaUrl(item.icon) ? (
                  <Box component="img" src={mediaUrl(item.icon)} alt="" sx={{ width: 36, height: 36 }} />
                ) : (
                  <Box
                    sx={{
                      width: 36,
                      height: 36,
                      borderRadius: "50%",
                      backgroundColor: "#17224d",
                    }}
                  />
                )}
              </Link>
            ))}
          </Stack>
          <Stack direction="row" alignItems="center" spacing={1}>
            {mediaUrl(data.phoneIcon) ? (
              <Box component="img" src={mediaUrl(data.phoneIcon)} alt="" sx={{ width: 18 }} />
            ) : null}
            <Typography sx={{ color: "#17224d", fontSize: 14, textAlign: { xs: "center", md: "left" } }}>
              {data.phones}
              {data.hours ? (
                <>
                  <br />
                  {data.hours}
                </>
              ) : null}
            </Typography>
          </Stack>
        </Stack>
      </Container>
    </Box>
  );
}
